-- =====================================================================
-- BARGO : catalogue de départ pour une installation neuve.
-- Généré depuis la copie PocketBase : jeux, boissons, boutique, questions du
-- quiz, bars et bar_boisson. AUCUNE donnée utilisateur.
-- INSERT OR IGNORE avec les identifiants PocketBase : relançable sans risque.
-- Colonnes image/fichier à NULL et pas de bar_image / jeu_image : les fichiers
-- arrivent avec scripts/migrer-pocketbase.mjs (ou par l'administration).
-- Exécuté après sql/schema.sql.
-- =====================================================================

-- Jeux
INSERT OR IGNORE INTO jeu (id, nom, description, type, created, updated) VALUES ('6ewf3fpr72odhil', 'Bargo Quiz Night', 'Un quiz fun et rapide pour tester tes connaissances sur les soirées, les bars, les défis entre amis et les bons réflexes pour rentrer en sécurité. Réponds aux questions, gagne des points, débloque des récompenses et montre à ton groupe que tu es le vrai boss du barathon. Inspiré de l’esprit Bargo, ce jeu mélange ambiance, stratégie et responsabilité pour rendre chaque sortie encore plus amusante.', 'questionaire', '2026-03-21T19:25:01.227Z', '2026-03-21T19:25:01.227Z');
INSERT OR IGNORE INTO jeu (id, nom, description, type, created, updated) VALUES ('shczn6ycjhb6st0', 'Memory Shot', 'Un jeu de mémoire rapide et fun où tu dois retrouver les bonnes paires le plus vite possible. Enchaîne les cartes, teste ta concentration et défie tes amis pour voir qui a la meilleure mémoire pendant la soirée. Simple, efficace et parfait pour ajouter une touche ludique à l’univers Bargo.', 'memorie', '2026-03-25T09:16:27.840Z', '2026-03-25T09:16:53.935Z');
INSERT OR IGNORE INTO jeu (id, nom, description, type, created, updated) VALUES ('7ru5sjakfq5ndpv', 'Reflex Tap', 'Un mini-jeu de réflexe simple et addictif. Le bouton reste en attente, puis passe soudainement au vert : dès qu’il s’allume, il faut cliquer le plus vite possible. Le jeu mesure ton temps de réaction en millisecondes et te permet de battre ton meilleur score.', 'reflex', '2026-06-03T08:18:00.555Z', '2026-06-03T08:18:00.555Z');
INSERT OR IGNORE INTO jeu (id, nom, description, type, created, updated) VALUES ('q0dx2kl9pxj3rd8', 'Drop Tap', 'Des blocs tombent depuis le haut de l’écran. Le but est de cliquer au bon moment, uniquement quand ils arrivent dans la zone du bas. Plus tu es précis, plus tu gagnes de points. Si tu cliques trop tôt, trop tard ou que tu rates un bloc, tu perds des points.', 'rythme', '2026-06-03T08:29:55.501Z', '2026-06-03T08:36:11.361Z');

